class Solution:
    def snakesAndLadders(self, board: list[list[int]]) -> int:
        from collections import deque
        n = len(board)
        def get_pos(s):
            r, c = divmod(s - 1, n)
            row = n - 1 - r
            col = c if r % 2 == 0 else n - 1 - c
            return row, col
        visited = set()
        queue = deque([(1, 0)])
        visited.add(1)
        target = n * n
        while queue:
            sq, moves = queue.popleft()
            for i in range(1, 7):
                nsq = sq + i
                if nsq > target:
                    break
                r, c = get_pos(nsq)
                if board[r][c] != -1:
                    nsq = board[r][c]
                if nsq == target:
                    return moves + 1
                if nsq not in visited:
                    visited.add(nsq)
                    queue.append((nsq, moves + 1))
        return -1

